contracts/TicketSale.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/utils/Counters.sol";
import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract TicketSale is ERC721, Ownable {
    using Counters for Counters.Counter;
    Counters.Counter private _tokenIdCounter;

    struct Ticket {
        string eventName;
        string eventOrganizer;
        string posterCid;
        string ticketImageUrl;
        uint128 price;
        uint64 expiryTimestamp;
        uint64 eventDate;
        address seller;
        address buyer;
        bool sold;
        bool downloaded;
        bool active;
    }

    struct TransactionHistory {
        address buyer;
        uint256 ticketId;
        uint128 price;
        string eventName;
        uint64 purchaseDate;
    }

    mapping(uint256 => Ticket) public tickets;
    mapping(uint256 => uint256) public escrowBalances;

    TransactionHistory[] public transactionHistories;

    uint256 public ticketCreationFee = 0.01 ether;
    address payable public admin;

    event TicketCreated(uint256 indexed ticketId, string eventName, string ticketImageUrl, string posterCid, bool active);
    event TicketBought(uint256 indexed ticketId, address buyer, uint256 price);
    event TicketDownloaded(uint256 indexed ticketId, address owner);
    event TicketRefunded(uint256 indexed ticketId, address buyer, uint256 refundAmount);
    event TicketStatusUpdated(uint256 indexed ticketId, bool active);
    event TransactionRecorded(address indexed buyer, uint256 indexed ticketId, uint128 price, string eventName, uint64 purchaseDate);

    constructor() ERC721("ConcertTicket", "CTIX") Ownable() {
        admin = payable(0xD55B57a32ffc78885F6A5F96016b5Dc87cb7BA06);
        _tokenIdCounter.increment();
    }

    modifier onlyActiveTicket(uint256 _ticketId) {
        require(tickets[_ticketId].active, "Ticket is inactive");
        _;
    }

    function createTicket(
        string memory _eventName,
        string memory _eventOrganizer,
        string memory _posterCid,
        string memory _ticketImageUrl,
        uint128 _price,
        uint64 _expiryTimestamp,
        uint64 _eventDate
    ) public payable {
        require(msg.value == ticketCreationFee, "Payment of 0.01 ETH required to create ticket");
        require(_expiryTimestamp > block.timestamp, "Expiry date must be in the future");
        require(_expiryTimestamp < _eventDate, "Expiry date must be before event date");
        require(bytes(_posterCid).length > 0, "Poster CID cannot be empty");

        (bool sent, ) = admin.call{value: msg.value}("");
        require(sent, "Failed to send fee to admin");

        uint256 newTicketId = _tokenIdCounter.current();
        _tokenIdCounter.increment();

        tickets[newTicketId] = Ticket({
            eventName: _eventName,
            eventOrganizer: _eventOrganizer,
            posterCid: _posterCid,
            ticketImageUrl: _ticketImageUrl,
            price: _price,
            expiryTimestamp: _expiryTimestamp,
            eventDate: _eventDate,
            seller: msg.sender,
            buyer: address(0),
            sold: false,
            downloaded: false,
            active: true
        });

        _mint(msg.sender, newTicketId); // NFT langsung dimiliki oleh seller

        emit TicketCreated(newTicketId, _eventName, _ticketImageUrl, _posterCid, true);
    }

    function createMultipleTickets(
    string memory _eventName,
    string memory _eventOrganizer,
    string memory _posterCid,
    string memory _ticketImageUrl,
    uint128 _price,
    uint64 _expiryTimestamp,
    uint64 _eventDate
) public payable {
    uint8 totalTickets = 5;
    require(msg.value == ticketCreationFee, "Payment of 0.01 ETH required");
    require(_expiryTimestamp > block.timestamp, "Expiry must be future");
    require(_expiryTimestamp < _eventDate, "Expiry must be before event date");
    require(bytes(_posterCid).length > 0, "Poster CID cannot be empty");

    (bool sent, ) = admin.call{value: msg.value}("");
    require(sent, "Failed to send fee to admin");

    for (uint8 i = 0; i < totalTickets; i++) {
        uint256 newTicketId = _tokenIdCounter.current();
        _tokenIdCounter.increment();

        tickets[newTicketId] = Ticket({
            eventName: _eventName,
            eventOrganizer: _eventOrganizer,
            posterCid: _posterCid,
            ticketImageUrl: _ticketImageUrl,
            price: _price,
            expiryTimestamp: _expiryTimestamp,
            eventDate: _eventDate,
            seller: msg.sender,
            buyer: address(0),
            sold: false,
            downloaded: false,
            active: true
        });

        _mint(msg.sender, newTicketId);

        emit TicketCreated(newTicketId, _eventName, _ticketImageUrl, _posterCid, true);
    }
}


    function buyTicket(uint256 _ticketId) public payable onlyActiveTicket(_ticketId) {
        Ticket storage ticket = tickets[_ticketId];
        require(!ticket.sold, "Ticket already sold");
        require(msg.value == ticket.price, "Incorrect payment amount");

        escrowBalances[_ticketId] = msg.value;
        ticket.buyer = msg.sender;
        ticket.sold = true;

        transactionHistories.push(TransactionHistory({
            buyer: msg.sender,
            ticketId: _ticketId,
            price: ticket.price,
            eventName: ticket.eventName,
            purchaseDate: uint64(block.timestamp)
        }));

        emit TransactionRecorded(msg.sender, _ticketId, ticket.price, ticket.eventName, uint64(block.timestamp));
        emit TicketBought(_ticketId, msg.sender, msg.value);
    }

    function markAsDownloaded(uint256 _ticketId) public onlyActiveTicket(_ticketId) {
        Ticket storage ticket = tickets[_ticketId];
        require(ticket.sold, "Ticket must be sold first");
        require(!ticket.downloaded, "Ticket already downloaded");
        require(ticket.buyer == msg.sender, "Only the buyer can mark the ticket as downloaded");

        ticket.downloaded = true;

        uint256 escrowAmount = escrowBalances[_ticketId];
        require(escrowAmount > 0, "No funds in escrow");

        // Transfer NFT from seller to buyer
        _transfer(ticket.seller, msg.sender, _ticketId);

        address seller = ticket.seller;
        escrowBalances[_ticketId] = 0;
        (bool sent, ) = seller.call{value: escrowAmount}("");
        require(sent, "Failed to transfer funds to seller");

        emit TicketDownloaded(_ticketId, msg.sender);
    }

    function updateExpiredTickets() public {
        for (uint256 i = 0; i < _tokenIdCounter.current(); i++) {
            Ticket storage ticket = tickets[i];
            if (ticket.active && ticket.expiryTimestamp < block.timestamp) {
                if (ticket.sold && !ticket.downloaded) {
                    uint256 refundAmount = escrowBalances[i];
                    escrowBalances[i] = 0;
                    address buyer = ticket.buyer;

                    (bool refunded, ) = buyer.call{value: refundAmount}("");
                    require(refunded, "Refund failed");

                    emit TicketRefunded(i, buyer, refundAmount);
                }
                ticket.active = false;
                emit TicketStatusUpdated(i, false);
            }
        }
    }

    function setAdmin(address payable _admin) public onlyOwner {
        admin = _admin;
    }

    function getTransactionHistory() public view returns (TransactionHistory[] memory) {
        return transactionHistories;
    }

    function getTicketDetails(uint256 _ticketId) public view returns (
        string memory eventName,
        address owner,
        bool active
    ) {
        Ticket memory ticket = tickets[_ticketId];
        return (ticket.eventName, ownerOf(_ticketId), ticket.active);
    }

    function getTicketCount() public view returns (uint256) {
        return _tokenIdCounter.current();
    }
}

